package oviewer

import (
	"bufio"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// Config holds all configuration settings
type Config struct {
	// Global settings
	QuitSmall          bool
	IsWriteOriginal    bool
	BeforeWriteOriginal int
	AfterWriteOriginal  int
	CaseSensitive      bool
	SmartCaseSensitive bool
	RegexpSearch       bool
	Incsearch          bool
	MemoryLimit        int
	MemoryLimitFile    int
	DisableMouse       bool
	DisableColumnCycle bool
	DisableStickyFollow bool
	ViewMode           string
	ClipboardMethod    string
	SetTerminalTitle   bool
	Debug              bool
	ShrinkChar         string
	ReadWaitTime       string
	DefaultKeyBind     string

	General GeneralConfig
	Mode    map[string]ModeConfig
	KeyBind map[string][]string
}

// GeneralConfig holds general display settings
type GeneralConfig struct {
	TabWidth         int
	Header           int
	SkipLines        int
	AlternateRows    bool
	ColumnMode       bool
	ColumnRainbow    bool
	ColumnWidth      bool
	LineNumMode      bool
	WrapMode         bool
	ColumnDelimiter  string
	MarkStyleWidth   int
	HScrollWidth     string
	VScrollLines     int
	SectionDelimiter string
	SectionHeader    bool
	SectionHeaderNum int
	SectionStart     int
	JumpTarget       string
	Converter        string
	HideOtherSection bool
	Plain            bool
	Raw              bool
	RulerMode        int
	StatusLine       bool
}

// ModeConfig holds per-mode configuration
type ModeConfig struct {
	TabWidth         int
	Header           int
	SkipLines        int
	AlternateRows    bool
	ColumnMode       bool
	ColumnRainbow    bool
	ColumnWidth      bool
	LineNumMode      bool
	WrapMode         bool
	ColumnDelimiter  string
	SectionDelimiter string
	SectionHeader    bool
	SectionHeaderNum int
	SectionStart     int
	JumpTarget       string
	Converter        string
}

// DefaultConfig returns a config with default values
func DefaultConfig() *Config {
	return &Config{
		Incsearch:       true,
		MemoryLimit:     -1,
		MemoryLimitFile: 100,
		General: GeneralConfig{
			TabWidth:        8,
			WrapMode:        true,
			ColumnDelimiter: ",",
			MarkStyleWidth:  1,
			HScrollWidth:    "10%",
			Converter:       "es",
			StatusLine:      true,
			SectionHeaderNum: 1,
		},
		Mode: make(map[string]ModeConfig),
	}
}

// LoadConfig loads configuration from a YAML file
// We implement a basic YAML parser since we don't have external packages
func LoadConfig(filename string) (*Config, error) {
	f, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	cfg := DefaultConfig()

	// Simple YAML parser
	scanner := bufio.NewScanner(f)
	var currentSection []string
	var currentMode string
	lineNum := 0

	for scanner.Scan() {
		lineNum++
		line := scanner.Text()

		// Skip comments and empty lines
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Determine indentation level
		indent := len(line) - len(strings.TrimLeft(line, " \t"))

		// Calculate section depth
		depth := indent / 2
		if indent > 0 && depth < len(currentSection) {
			currentSection = currentSection[:depth]
		}

		// Check for key: value
		if colonIdx := strings.Index(trimmed, ":"); colonIdx > 0 {
			key := strings.TrimSpace(trimmed[:colonIdx])
			value := strings.TrimSpace(trimmed[colonIdx+1:])

			// Remove inline comments
			if commentIdx := strings.Index(value, " #"); commentIdx >= 0 {
				value = strings.TrimSpace(value[:commentIdx])
			}

			// Strip quotes
			if len(value) >= 2 && ((value[0] == '"' && value[len(value)-1] == '"') ||
				(value[0] == '\'' && value[len(value)-1] == '\'')) {
				value = value[1 : len(value)-1]
			}

			// Handle value-less keys (sections)
			if value == "" {
				if depth == 0 {
					if key == "General" {
						currentSection = []string{"General"}
						currentMode = ""
					} else if key == "Mode" {
						currentSection = []string{"Mode"}
						currentMode = ""
					} else if key == "KeyBind" {
						currentSection = []string{"KeyBind"}
						currentMode = ""
					} else if key == "Style" {
						// Skip style sections
					} else if key == "Prompt" {
						// Skip prompt sections
					}
				} else if len(currentSection) >= 1 && currentSection[0] == "Mode" && depth == 1 {
					currentMode = key
					if cfg.Mode == nil {
						cfg.Mode = make(map[string]ModeConfig)
					}
					mc := ModeConfig{
						WrapMode:        true,
						ColumnDelimiter: ",",
					}
					cfg.Mode[currentMode] = mc
				}
				continue
			}

			// Apply the value
			section := ""
			if len(currentSection) > 0 {
				section = currentSection[0]
			}

			switch section {
			case "":
				applyGlobalConfig(cfg, key, value)
			case "General":
				applyGeneralConfig(&cfg.General, key, value)
			case "Mode":
				if currentMode != "" {
					mc := cfg.Mode[currentMode]
					applyModeConfig(&mc, key, value)
					cfg.Mode[currentMode] = mc
				}
			case "KeyBind":
				// Handle keybind list items
			}
		} else if strings.HasPrefix(trimmed, "- ") {
			// List item - for keybinds
		}
	}

	return cfg, scanner.Err()
}

func applyGlobalConfig(cfg *Config, key, value string) {
	switch key {
	case "QuitSmall":
		cfg.QuitSmall = parseBool(value)
	case "IsWriteOriginal":
		cfg.IsWriteOriginal = parseBool(value)
	case "CaseSensitive":
		cfg.CaseSensitive = parseBool(value)
	case "SmartCaseSensitive":
		cfg.SmartCaseSensitive = parseBool(value)
	case "RegexpSearch":
		cfg.RegexpSearch = parseBool(value)
	case "Incsearch":
		cfg.Incsearch = parseBool(value)
	case "MemoryLimit":
		cfg.MemoryLimit, _ = strconv.Atoi(value)
	case "MemoryLimitFile":
		cfg.MemoryLimitFile, _ = strconv.Atoi(value)
	case "DisableMouse":
		cfg.DisableMouse = parseBool(value)
	case "DisableColumnCycle":
		cfg.DisableColumnCycle = parseBool(value)
	case "ViewMode":
		cfg.ViewMode = value
	case "SetTerminalTitle":
		cfg.SetTerminalTitle = parseBool(value)
	case "Debug":
		cfg.Debug = parseBool(value)
	}
}

func applyGeneralConfig(g *GeneralConfig, key, value string) {
	switch key {
	case "TabWidth":
		g.TabWidth, _ = strconv.Atoi(value)
	case "Header":
		g.Header, _ = strconv.Atoi(value)
	case "AlternateRows":
		g.AlternateRows = parseBool(value)
	case "ColumnMode":
		g.ColumnMode = parseBool(value)
	case "LineNumMode":
		g.LineNumMode = parseBool(value)
	case "WrapMode":
		g.WrapMode = parseBool(value)
	case "ColumnDelimiter":
		g.ColumnDelimiter = value
	case "MarkStyleWidth":
		g.MarkStyleWidth, _ = strconv.Atoi(value)
	case "HScrollWidth":
		g.HScrollWidth = value
	case "SectionDelimiter":
		g.SectionDelimiter = value
	case "SectionHeaderNum":
		g.SectionHeaderNum, _ = strconv.Atoi(value)
	case "Converter":
		g.Converter = value
	case "StatusLine":
		g.StatusLine = parseBool(value)
	}
}

func applyModeConfig(m *ModeConfig, key, value string) {
	switch key {
	case "TabWidth":
		m.TabWidth, _ = strconv.Atoi(value)
	case "Header":
		m.Header, _ = strconv.Atoi(value)
	case "AlternateRows":
		m.AlternateRows = parseBool(value)
	case "ColumnMode":
		m.ColumnMode = parseBool(value)
	case "LineNumMode":
		m.LineNumMode = parseBool(value)
	case "WrapMode":
		m.WrapMode = parseBool(value)
	case "ColumnDelimiter":
		m.ColumnDelimiter = value
	case "SectionDelimiter":
		m.SectionDelimiter = value
	case "SectionHeaderNum":
		m.SectionHeaderNum, _ = strconv.Atoi(value)
	}
}

func parseBool(s string) bool {
	s = strings.ToLower(strings.TrimSpace(s))
	return s == "true" || s == "yes" || s == "1"
}

// GetConfigPath returns the default config file path
func GetConfigPath() string {
	configDir := os.Getenv("XDG_CONFIG_HOME")
	if configDir == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return ""
		}
		configDir = filepath.Join(home, ".config")
	}
	return filepath.Join(configDir, "ov", "config.yaml")
}
GOEOF
