package oviewer

import (
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"unicode"
	"unicode/utf8"

	"golang.org/x/term"
)

// Terminal control sequences
const (
	ESC = "\x1b"
	CSI = "\x1b["

	// Cursor movement
	CursorHome   = CSI + "H"
	CursorUp     = CSI + "A"
	CursorDown   = CSI + "B"
	CursorRight  = CSI + "C"
	CursorLeft   = CSI + "D"

	// Screen control
	ClearScreen     = CSI + "2J"
	ClearToEOL      = CSI + "K"
	ClearFromCursor = CSI + "J"

	// Cursor visibility
	HideCursor = CSI + "?25l"
	ShowCursor = CSI + "?25h"

	// Terminal modes
	EnterAltScreen = CSI + "?1049h"
	ExitAltScreen  = CSI + "?1049l"

	// Mouse
	EnableMouseTracking  = CSI + "?1000h" + CSI + "?1006h"
	DisableMouseTracking = CSI + "?1000l" + CSI + "?1006l"

	// Colors/attributes
	AttrReset     = CSI + "0m"
	AttrBold      = CSI + "1m"
	AttrDim       = CSI + "2m"
	AttrItalic    = CSI + "3m"
	AttrUnderline = CSI + "4m"
	AttrReverse   = CSI + "7m"

	// Standard colors (30-37 fg, 40-47 bg)
	ColorReset = CSI + "0m"
)

// Screen manages the terminal display
type Screen struct {
	fd       int
	oldState *term.State
	width    int
	height   int
	buf      *os.File

	// Signals
	sigChan chan os.Signal

	// Enabled features
	mouseEnabled bool
	altScreen    bool
}

// NewScreen creates a new screen manager
func NewScreen(disableMouse bool) (*Screen, error) {
	// Try to open /dev/tty for terminal control
	var ttyFd int
	var ttyFile *os.File

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		// Fall back to stdout
		if !term.IsTerminal(int(os.Stdout.Fd())) {
			return nil, fmt.Errorf("Screen.Init(): open /dev/tty: %v", err)
		}
		ttyFd = int(os.Stdout.Fd())
		ttyFile = os.Stdout
	} else {
		ttyFd = int(tty.Fd())
		ttyFile = tty
	}

	s := &Screen{
		fd:      ttyFd,
		buf:     ttyFile,
		sigChan: make(chan os.Signal, 1),
	}

	// Get terminal size
	if err := s.updateSize(); err != nil {
		return nil, err
	}

	return s, nil
}

// Init initializes the screen (enter raw mode, alt screen)
func (s *Screen) Init() error {
	var err error
	s.oldState, err = term.MakeRaw(s.fd)
	if err != nil {
		return err
	}

	// Enter alternate screen
	fmt.Fprint(s.buf, EnterAltScreen)
	fmt.Fprint(s.buf, HideCursor)
	s.altScreen = true

	// Enable mouse tracking
	if s.mouseEnabled {
		fmt.Fprint(s.buf, EnableMouseTracking)
	}

	// Handle SIGWINCH
	signal.Notify(s.sigChan, syscall.SIGWINCH)

	return nil
}

// Close restores the terminal
func (s *Screen) Close() {
	if s.altScreen {
		if s.mouseEnabled {
			fmt.Fprint(s.buf, DisableMouseTracking)
		}
		fmt.Fprint(s.buf, ShowCursor)
		fmt.Fprint(s.buf, ExitAltScreen)
		s.altScreen = false
	}

	if s.oldState != nil {
		term.Restore(s.fd, s.oldState)
		s.oldState = nil
	}

	signal.Stop(s.sigChan)
}

// updateSize updates the terminal size
func (s *Screen) updateSize() error {
	w, h, err := term.GetSize(s.fd)
	if err != nil {
		return err
	}
	s.width = w
	s.height = h
	return nil
}

// Width returns the terminal width
func (s *Screen) Width() int {
	return s.width
}

// Height returns the terminal height
func (s *Screen) Height() int {
	return s.height
}

// MoveTo moves the cursor to a position (1-based)
func (s *Screen) MoveTo(row, col int) {
	fmt.Fprintf(s.buf, "%s%d;%dH", CSI, row, col)
}

// Clear clears the screen
func (s *Screen) Clear() {
	fmt.Fprint(s.buf, CursorHome)
	fmt.Fprint(s.buf, ClearScreen)
}

// ClearLine clears from cursor to end of line
func (s *Screen) ClearLine() {
	fmt.Fprint(s.buf, ClearToEOL)
}

// SetStyle sets text attributes
func (s *Screen) SetStyle(style Style) {
	fmt.Fprint(s.buf, style.ToANSI())
}

// ResetStyle resets all text attributes
func (s *Screen) ResetStyle() {
	fmt.Fprint(s.buf, AttrReset)
}

// WriteString writes a string at current cursor position
func (s *Screen) WriteString(str string) {
	fmt.Fprint(s.buf, str)
}

// DrawLine draws content at a specific row
func (s *Screen) DrawLine(row int, content []Cell, width int) {
	s.MoveTo(row, 1)
	s.ResetStyle()

	col := 0
	for _, cell := range content {
		if col >= width {
			break
		}
		if cell.Style != (Style{}) {
			fmt.Fprint(s.buf, cell.Style.ToANSI())
		}
		fmt.Fprint(s.buf, string(cell.Rune))
		if cell.Style != (Style{}) {
			fmt.Fprint(s.buf, AttrReset)
		}
		col += runeWidth(cell.Rune)
	}

	// Clear the rest of the line
	if col < width {
		fmt.Fprint(s.buf, ClearToEOL)
	}
}

// SigWinch returns the signal channel for SIGWINCH
func (s *Screen) SigWinch() <-chan os.Signal {
	return s.sigChan
}

// Style represents text styling
type Style struct {
	Foreground string
	Background string
	Bold       bool
	Italic     bool
	Underline  bool
	Reverse    bool
	Dim        bool
}

// ToANSI converts a Style to ANSI escape sequence
func (st Style) ToANSI() string {
	var sb strings.Builder
	sb.WriteString(CSI)

	codes := []string{"0"}

	if st.Bold {
		codes = append(codes, "1")
	}
	if st.Dim {
		codes = append(codes, "2")
	}
	if st.Italic {
		codes = append(codes, "3")
	}
	if st.Underline {
		codes = append(codes, "4")
	}
	if st.Reverse {
