	AttrItalic    = CSI + "3m"
	AttrUnderline = CSI + "4m"
	AttrReverse   = CSI + "7m"

	// Standard colors (30-37 fg, 40-47 bg)
	ColorReset = CSI + "0m"
)

// Screen manages the terminal display
type Screen struct {
	fd       int
	oldState *term.State
	width    int
	height   int
	buf      *os.File

	// Signals
	sigChan chan os.Signal

	// Enabled features
	mouseEnabled bool
	altScreen    bool
}

// NewScreen creates a new screen manager
func NewScreen(disableMouse bool) (*Screen, error) {
	// Try to open /dev/tty for terminal control
	var ttyFd int
	var ttyFile *os.File

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		// Fall back to stdout
		if !term.IsTerminal(int(os.Stdout.Fd())) {
			return nil, fmt.Errorf("Screen.Init(): open /dev/tty: %v", err)
		}
		ttyFd = int(os.Stdout.Fd())
		ttyFile = os.Stdout
	} else {
		ttyFd = int(tty.Fd())
		ttyFile = tty
	}

	s := &Screen{
		fd:      ttyFd,
		buf:     ttyFile,
		sigChan: make(chan os.Signal, 1),
	}

	// Get terminal size
	if err := s.updateSize(); err != nil {
		return nil, err
	}

	return s, nil
}

// Init initializes the screen (enter raw mode, alt screen)
func (s *Screen) Init() error {
	var err error
	s.oldState, err = term.MakeRaw(s.fd)
	if err != nil {
		return err
	}

	// Enter alternate screen
	fmt.Fprint(s.buf, EnterAltScreen)
	fmt.Fprint(s.buf, HideCursor)
	s.altScreen = true

	// Enable mouse tracking
	if s.mouseEnabled {
		fmt.Fprint(s.buf, EnableMouseTracking)
	}

	// Handle SIGWINCH
	signal.Notify(s.sigChan, syscall.SIGWINCH)

	return nil
}

// Close restores the terminal
func (s *Screen) Close() {
	if s.altScreen {
		if s.mouseEnabled {
			fmt.Fprint(s.buf, DisableMouseTracking)
		}
		fmt.Fprint(s.buf, ShowCursor)
		fmt.Fprint(s.buf, ExitAltScreen)
		s.altScreen = false
	}

	if s.oldState != nil {
		term.Restore(s.fd, s.oldState)
		s.oldState = nil
	}

	signal.Stop(s.sigChan)
}

// updateSize updates the terminal size
func (s *Screen) updateSize() error {
	w, h, err := term.GetSize(s.fd)
	if err != nil {
		return err
	}
	s.width = w
	s.height = h
	return nil
}

// Width returns the terminal width
func (s *Screen) Width() int {
	return s.width
}

// Height returns the terminal height
func (s *Screen) Height() int {
	return s.height
}

// MoveTo moves the cursor to a position (1-based)
func (s *Screen) MoveTo(row, col int) {
	fmt.Fprintf(s.buf, "%s%d;%dH", CSI, row, col)
}

// Clear clears the screen
func (s *Screen) Clear() {
	fmt.Fprint(s.buf, CursorHome)
	fmt.Fprint(s.buf, ClearScreen)
}

// ClearLine clears from cursor to end of line
func (s *Screen) ClearLine() {
	fmt.Fprint(s.buf, ClearToEOL)
}

// SetStyle sets text attributes
func (s *Screen) SetStyle(style Style) {
	fmt.Fprint(s.buf, style.ToANSI())
}

// ResetStyle resets all text attributes
func (s *Screen) ResetStyle() {
	fmt.Fprint(s.buf, AttrReset)
}

// WriteString writes a string at current cursor position
func (s *Screen) WriteString(str string) {
	fmt.Fprint(s.buf, str)
}

// DrawLine draws content at a specific row
func (s *Screen) DrawLine(row int, content []Cell, width int) {
	s.MoveTo(row, 1)
	s.ResetStyle()

	col := 0
	for _, cell := range content {
		if col >= width {
			break
		}
		if cell.Style != (Style{}) {
			fmt.Fprint(s.buf, cell.Style.ToANSI())
		}
		fmt.Fprint(s.buf, string(cell.Rune))
		if cell.Style != (Style{}) {
			fmt.Fprint(s.buf, AttrReset)
		}
		col += runeWidth(cell.Rune)
	}

	// Clear the rest of the line
	if col < width {
		fmt.Fprint(s.buf, ClearToEOL)
	}
}

// SigWinch returns the signal channel for SIGWINCH
func (s *Screen) SigWinch() <-chan os.Signal {
	return s.sigChan
}

// Style represents text styling
type Style struct {
	Foreground string
	Background string
	Bold       bool
	Italic     bool
	Underline  bool
	Reverse    bool
	Dim        bool
}

// ToANSI converts a Style to ANSI escape sequence
func (st Style) ToANSI() string {
	var sb strings.Builder
	sb.WriteString(CSI)

	codes := []string{"0"}

	if st.Bold {
		codes = append(codes, "1")
	}
	if st.Dim {
		codes = append(codes, "2")
	}
	if st.Italic {
		codes = append(codes, "3")
	}
	if st.Underline {
		codes = append(codes, "4")
	}
	if st.Reverse {
		codes = append(codes, "7")
	}

	if st.Foreground != "" {
		code := colorCode(st.Foreground, false)
		if code != "" {
			codes = append(codes, code)
		}
	}
	if st.Background != "" {
		code := colorCode(st.Background, true)
		if code != "" {
			codes = append(codes, code)
		}
	}

	for i, c := range codes {
		if i > 0 {
			sb.WriteByte(';')
		}
		sb.WriteString(c)
	}
	sb.WriteByte('m')

	return sb.String()
}

// colorCode returns the ANSI color code for a named color
func colorCode(name string, bg bool) string {
	offset := 30
	if bg {
		offset = 40
	}

	// Handle hex colors
	if strings.HasPrefix(name, "#") {
		// Parse hex color for 24-bit color
		if len(name) == 7 {
			var r, g, b int
			fmt.Sscanf(name[1:], "%02x%02x%02x", &r, &g, &b)
			if bg {
				return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
			}
			return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
		}
	}

	// Named colors
	switch strings.ToLower(name) {
	case "black":
		return fmt.Sprintf("%d", offset+0)
	case "red", "maroon":
		return fmt.Sprintf("%d", offset+1)
	case "green":
		return fmt.Sprintf("%d", offset+2)
	case "yellow", "olive":
		return fmt.Sprintf("%d", offset+3)
	case "blue", "navy":
		return fmt.Sprintf("%d", offset+4)
	case "magenta", "purple", "fuchsia":
		return fmt.Sprintf("%d", offset+5)
	case "cyan", "teal", "aqua":
		return fmt.Sprintf("%d", offset+6)
	case "white", "silver":
		return fmt.Sprintf("%d", offset+7)
	case "gray", "grey", "darkgray", "darkgrey":
		return fmt.Sprintf("%d", offset+60+0)
	case "brightred", "crimson", "darkred":
		return fmt.Sprintf("%d", offset+60+1)
	case "brightgreen", "lime", "limegreen":
		return fmt.Sprintf("%d", offset+60+2)
	case "brightyellow":
		return fmt.Sprintf("%d", offset+60+3)
	case "brightblue", "royalblue":
		return fmt.Sprintf("%d", offset+60+4)
	case "brightmagenta":
		return fmt.Sprintf("%d", offset+60+5)
	case "brightcyan":
		return fmt.Sprintf("%d", offset+60+6)
	case "brightwhite":
		return fmt.Sprintf("%d", offset+60+7)
	case "darkgoldenrod":
		// Use 256-color approximation
		if bg {
			return "48;5;136"
		}
		return "38;5;136"
	case "slateblue":
		if bg {
			return "48;5;62"
		}
		return "38;5;62"
	}

	return ""
}

// Cell represents a single terminal cell
type Cell struct {
	Rune  rune
	Style Style
}

// runeWidth returns the visual width of a rune
func runeWidth(r rune) int {
	if r < 32 {
		return 0
	}
	if unicode.Is(unicode.Han, r) || unicode.Is(unicode.Katakana, r) || unicode.Is(unicode.Hiragana, r) {
		return 2
	}
	return 1
}

// stringWidth returns the visual width of a string (ignoring ANSI codes)
func stringWidth(s string) int {
	width := 0
	inEscape := false
	for _, r := range s {
		if inEscape {
			if r == 'm' || r == 'H' || r == 'J' || r == 'K' || unicode.IsLetter(r) {
				inEscape = false
			}
			continue
		}
		if r == '\x1b' {
			inEscape = true
			continue
		}
		width += runeWidth(r)
	}
	return width
}

// truncateToWidth truncates a string to fit within the given display width
func truncateToWidth(s string, maxWidth int) string {
	width := 0
	for i, r := range s {
		w := runeWidth(r)
		if width+w > maxWidth {
			return s[:i]
		}
		width += w
		_ = utf8.ValidString(s[i:]) // just to avoid unused import
	}
	return s
}

// ReadKey reads a keypress from the terminal
func ReadKey(fd int) (Key, error) {
	buf := make([]byte, 256)
	n, err := syscall.Read(fd, buf[:1])
	if err != nil || n == 0 {
		return Key{}, err
	}

	// Check for escape sequences
	if buf[0] == 0x1b {
		// Set non-blocking read for the rest
		// Try to read more bytes
		buf[1] = 0
		n2, _ := syscall.Read(fd, buf[1:2])
		if n2 == 0 {
			return Key{Name: "Escape"}, nil
		}

		if buf[1] == '[' {
			// CSI sequence
			n3, _ := syscall.Read(fd, buf[2:64])
			seq := string(buf[2 : 2+n3])
			return parseCSI(seq), nil
		} else if buf[1] == 'O' {
			n3, _ := syscall.Read(fd, buf[2:3])
			if n3 > 0 {
				return parseSS3(buf[2]), nil
			}
		} else {
			// Alt + key
			return Key{Name: string(buf[1:2]), Alt: true}, nil
		}
	}

	// Regular character
	if buf[0] == 0x0d || buf[0] == 0x0a {
		return Key{Name: "Enter"}, nil
	}
	if buf[0] == 0x7f || buf[0] == 0x08 {
		return Key{Name: "Backspace"}, nil
	}
	if buf[0] < 0x20 {
		return Key{Name: ctrlKey(buf[0]), Ctrl: true}, nil
	}

	// Multi-byte UTF-8
	if buf[0] >= 0x80 {
		// Read remaining bytes
		n2, _ := syscall.Read(fd, buf[1:4])
		r, _ := utf8.DecodeRune(buf[:1+n2])
		return Key{Rune: r, Name: string(r)}, nil
	}

	return Key{Rune: rune(buf[0]), Name: string(buf[0])}, nil
}

// ctrlKey returns the name of a control character
func ctrlKey(b byte) string {
	return fmt.Sprintf("ctrl+%c", b+0x60)
}

// parseCSI parses a CSI escape sequence
func parseCSI(seq string) Key {
	if len(seq) == 0 {
		return Key{Name: "Unknown"}
	}

	// Check for modifier codes
	// Format: [modifier;]final_byte
	// e.g., "1;5A" = Ctrl+Up

	switch seq {
	case "A":
		return Key{Name: "Up"}
	case "B":
		return Key{Name: "Down"}
	case "C":
		return Key{Name: "Right"}
	case "D":
		return Key{Name: "Left"}
	case "H":
		return Key{Name: "Home"}
	case "F":
		return Key{Name: "End"}
	case "1~":
		return Key{Name: "Home"}
	case "2~":
		return Key{Name: "Insert"}
	case "3~":
		return Key{Name: "Delete"}
	case "4~":
		return Key{Name: "End"}
	case "5~":
		return Key{Name: "PageUp"}
	case "6~":
		return Key{Name: "PageDown"}
	case "7~":
		return Key{Name: "Home"}
	case "8~":
		return Key{Name: "End"}
	case "11~", "P":
		return Key{Name: "F1"}
	case "12~", "Q":
		return Key{Name: "F2"}
	case "13~", "R":
		return Key{Name: "F3"}
	case "14~", "S":
		return Key{Name: "F4"}
	case "15~":
		return Key{Name: "F5"}
	case "17~":
		return Key{Name: "F6"}
	case "18~":
		return Key{Name: "F7"}
	case "19~":
		return Key{Name: "F8"}
	case "20~":
		return Key{Name: "F9"}
	case "21~":
		return Key{Name: "F10"}
	case "23~":
		return Key{Name: "F11"}
	case "24~":
		return Key{Name: "F12"}
	case "Z":
		return Key{Name: "Tab", Shift: true}
	}

	// Parse modifier sequences like "1;2A" (Shift+Up)
	if len(seq) > 2 && strings.Contains(seq, ";") {
		parts := strings.Split(seq, ";")
		if len(parts) == 2 {
			modStr := parts[0]
			finalSeq := parts[1]
			if modStr == "1" {
				modStr = ""
			}
			// Parse modifier: 2=Shift, 3=Alt, 4=Shift+Alt, 5=Ctrl, 6=Shift+Ctrl, 7=Ctrl+Alt
			var k Key
			switch finalSeq {
			case "A":
				k.Name = "Up"
			case "B":
				k.Name = "Down"
			case "C":
				k.Name = "Right"
			case "D":
				k.Name = "Left"
			case "F":
				k.Name = "End"
			case "H":
				k.Name = "Home"
			default:
				// Handle Fn keys with modifiers
				if strings.HasSuffix(finalSeq, "~") {
					inner := parseCSI(finalSeq)
					k.Name = inner.Name
				}
			}
			switch modStr {
			case "2":
				k.Shift = true
			case "3":
				k.Alt = true
			case "4":
				k.Shift = true
				k.Alt = true
			case "5":
				k.Ctrl = true
			case "6":
				k.Shift = true
				k.Ctrl = true
			case "7":
				k.Ctrl = true
				k.Alt = true
			case "8":
				k.Shift = true
				k.Ctrl = true
				k.Alt = true
			}
			if k.Name != "" {
				return k
			}
		}
	}

	return Key{Name: "CSI:" + seq}
}

// parseSS3 parses an SS3 escape sequence (ESC O x)
func parseSS3(b byte) Key {
	switch b {
	case 'A':
		return Key{Name: "Up"}
	case 'B':
		return Key{Name: "Down"}
	case 'C':
		return Key{Name: "Right"}
	case 'D':
		return Key{Name: "Left"}
	case 'H':
		return Key{Name: "Home"}
	case 'F':
		return Key{Name: "End"}
	case 'P':
		return Key{Name: "F1"}
	case 'Q':
		return Key{Name: "F2"}
	case 'R':
		return Key{Name: "F3"}
	case 'S':
		return Key{Name: "F4"}
	}
	return Key{Name: "SS3:" + string(b)}
}

// Key represents a keypress
type Key struct {
	Rune  rune
	Name  string
	Ctrl  bool
	Alt   bool
	Shift bool
}

// String returns a string representation of the key
func (k Key) String() string {
	s := k.Name
	if s == "" {
		s = string(k.Rune)
	}
	if k.Ctrl {
		s = "ctrl+" + s
	}
	if k.Alt {
		s = "alt+" + s
	}
	if k.Shift {
		s = "shift+" + s
	}
	return s
}
