package oviewer

import (
	"bufio"
	"compress/bzip2"
	"compress/gzip"
	"io"
	"os"
	"strings"
)

// Document holds the content of a file or stdin
type Document struct {
	Name    string
	lines   []string
	loaded  bool
	readErr error
}

// NewDocument creates a new document from a file
func NewDocument(name string, skipExtract bool) (*Document, error) {
	doc := &Document{
		Name: name,
	}

	var r io.Reader

	if name == "" || name == "-" {
		r = os.Stdin
		doc.Name = ""
	} else {
		f, err := os.Open(name)
		if err != nil {
			return nil, err
		}
		defer f.Close()

		if !skipExtract {
			r = decompressReader(f, name)
		} else {
			// Read the file fully first then reassign
			r = f
		}

		// Read all content
		if err := doc.readAll(r); err != nil {
			return nil, err
		}
		return doc, nil
	}

	if err := doc.readAll(r); err != nil {
		return nil, err
	}
	return doc, nil
}

// decompressReader wraps a reader with decompression if needed
func decompressReader(r io.Reader, name string) io.Reader {
	lower := strings.ToLower(name)

	if strings.HasSuffix(lower, ".gz") {
		gr, err := gzip.NewReader(r)
		if err != nil {
			return r
		}
		return gr
	}

	if strings.HasSuffix(lower, ".bz2") {
		return bzip2.NewReader(r)
	}

	// For xz, zstd, lz4 - return raw reader since we can't decompress them
	// without external packages
	return r
}

// readAll reads all lines from a reader
func (doc *Document) readAll(r io.Reader) error {
	scanner := bufio.NewScanner(r)
	// Increase buffer size for long lines
	buf := make([]byte, 1024*1024)
	scanner.Buffer(buf, 1024*1024)

	for scanner.Scan() {
		doc.lines = append(doc.lines, scanner.Text())
	}

	doc.loaded = true
	doc.readErr = scanner.Err()
	return doc.readErr
}

// LineCount returns the number of lines
func (doc *Document) LineCount() int {
	return len(doc.lines)
}

// GetLine returns the line at index i
func (doc *Document) GetLine(i int) string {
	if i < 0 || i >= len(doc.lines) {
		return ""
	}
	return doc.lines[i]
}

// IsLoaded returns whether the document is fully loaded
func (doc *Document) IsLoaded() bool {
	return doc.loaded
}
