	// Window dimensions
	contentHeight int // height for content (height - status line)

	// Input history
	searchHistory []string
	searchHistIdx int

	// Exit write buffer
	exitLines []string
}

// NewViewer creates a new viewer
func NewViewer(doc *Document, screen *Screen, opts *Options) *Viewer {
	v := &Viewer{
		screen:          screen,
		doc:             doc,
		opts:            opts,
		wrapMode:        opts.WrapMode,
		lineNumMode:     opts.LineNumMode,
		alternateRows:   opts.AlternateRows,
		columnMode:      opts.ColumnMode,
		header:          opts.Header,
		tabWidth:        opts.TabWidth,
		columnDelimiter: opts.ColumnDelimiter,
		plain:           opts.Plain,
		statusLine:      opts.StatusLine,
		searchDown:      true,
	}
	v.contentHeight = screen.Height() - 1
	if !v.statusLine {
		v.contentHeight = screen.Height()
	}

	// Set initial jump target
	if opts.Pattern != "" {
		v.search = opts.Pattern
		v.searchDown = true
		// Find the first match
		v.compileSearch(opts.Pattern, opts.CaseSensitive, opts.RegexpSearch)
		v.findNext(false)
	}

	return v
}

// Run is the main event loop
func (v *Viewer) Run() error {
	// Initial render
	v.render()

	// Check if we should quit immediately (QuitSmall / --quit-if-one-screen)
	if v.opts.QuitSmall {
		if v.doc.LineCount() <= v.contentHeight {
			return nil
		}
	}

	// Main event loop
	for {
		key, err := ReadKey(v.screen.fd)
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}

		// Handle resize
		select {
		case <-v.screen.SigWinch():
			v.screen.updateSize()
			v.contentHeight = v.screen.Height() - 1
			if !v.statusLine {
				v.contentHeight = v.screen.Height()
			}
			v.render()
			continue
		default:
		}

		if v.mode != ModeNormal {
			if v.handleInputMode(key) {
				return nil
			}
			v.render()
			continue
		}

		if v.handleKey(key) {
			return nil
		}
		v.render()
	}
}

// handleKey handles a keypress in normal mode
// Returns true if viewer should exit
func (v *Viewer) handleKey(key Key) bool {
	switch {
	case key.Name == "Escape" || key.Name == "q":
		return true

	case key.Name == "Q":
