// Viewer is the main TUI viewer
type Viewer struct {
	screen *Screen
	doc    *Document
	opts   *Options

	// Current view state
	topLine  int // Current top line index (0-based)
	leftCol  int // Current left column offset

	// Display state
	mode     int    // Current input mode
