}

// handleInputMode handles keys in input mode
func (v *Viewer) handleInputMode(key Key) bool {
	switch key.Name {
	case "Escape", "ctrl+c":
		v.mode = ModeNormal
		v.inputBuf = ""
		return false

	case "Enter":
		v.executeInput()
		v.mode = ModeNormal
		return false

	case "Backspace":
		if len(v.inputBuf) > 0 {
			_, size := utf8.DecodeLastRuneInString(v.inputBuf)
			v.inputBuf = v.inputBuf[:len(v.inputBuf)-size]
		}
		if v.mode == ModeSearch || v.mode == ModeBackSearch {
			if opts := v.opts; opts.Incsearch {
				v.performIncSearch()
			}
		}
		return false

	case "Up":
		if len(v.searchHistory) > 0 {
			if v.searchHistIdx < len(v.searchHistory) {
				v.searchHistIdx++
			}
			idx := len(v.searchHistory) - v.searchHistIdx
			if idx >= 0 && idx < len(v.searchHistory) {
				v.inputBuf = v.searchHistory[idx]
			}
		}
		return false

	case "Down":
		if v.searchHistIdx > 0 {
			v.searchHistIdx--
		}
		if v.searchHistIdx == 0 {
			v.inputBuf = ""
		} else {
			idx := len(v.searchHistory) - v.searchHistIdx
			if idx >= 0 && idx < len(v.searchHistory) {
				v.inputBuf = v.searchHistory[idx]
			}
		}
		return false
	}

	// Regular character input
	if key.Rune != 0 {
		v.inputBuf += string(key.Rune)
		if v.mode == ModeSearch || v.mode == ModeBackSearch {
			if opts := v.opts; opts.Incsearch {
				v.performIncSearch()
			}
		}
	}

	return false
}

// executeInput executes the current input buffer based on mode
func (v *Viewer) executeInput() {
	input := v.inputBuf

	switch v.mode {
	case ModeSearch:
		v.lastSearch = input
		v.searchDown = true
		if input != "" {
			v.searchHistory = append(v.searchHistory, input)
		}
		v.compileSearch(input, v.opts.CaseSensitive, v.opts.RegexpSearch)
		v.findNext(false)

	case ModeBackSearch:
		v.lastSearch = input
		v.searchDown = false
		if input != "" {
			v.searchHistory = append(v.searchHistory, input)
		}
		v.compileSearch(input, v.opts.CaseSensitive, v.opts.RegexpSearch)
		v.findNext(false)

	case ModeGoto:
		v.gotoLine(input)

	case ModeHeader:
		n, err := strconv.Atoi(input)
		if err == nil && n >= 0 {
			v.header = n
		}

	case ModeDelimiter:
		if input != "" {
			v.columnDelimiter = input
		}

	case ModeTabWidth:
		n, err := strconv.Atoi(input)
		if err == nil && n > 0 {
			v.tabWidth = n
		}

	case ModeSkipLines:
		n, err := strconv.Atoi(input)
		if err == nil && n >= 0 {
			v.opts.SkipLines = n
		}

	case ModeJumpTarget:
		v.opts.JumpTarget = input
	}
}

// performIncSearch performs incremental search
func (v *Viewer) performIncSearch() {
	if v.inputBuf == "" {
		v.searchPattern = nil
		return
	}
	savedTop := v.topLine
	v.compileSearch(v.inputBuf, v.opts.CaseSensitive, v.opts.RegexpSearch)
	if v.searchPattern != nil {
		// Search from current position
		startLine := v.topLine
		if v.searchDown {
			for i := startLine; i < v.doc.LineCount(); i++ {
				line := v.doc.GetLine(i)
				if v.searchPattern.MatchString(line) {
					v.topLine = i
					return
				}
			}
		}
	}
	v.topLine = savedTop
}

// compileSearch compiles the search pattern
func (v *Viewer) compileSearch(pattern string, caseSensitive, regexpSearch bool) {
	if pattern == "" {
		v.searchPattern = nil
		return
	}

	var re *regexp.Regexp
	var err error

	if regexpSearch {
		if caseSensitive {
			re, err = regexp.Compile(pattern)
		} else {
			re, err = regexp.Compile("(?i)" + pattern)
		}
	} else {
		escaped := regexp.QuoteMeta(pattern)
		if caseSensitive {
			re, err = regexp.Compile(escaped)
		} else {
			re, err = regexp.Compile("(?i)" + escaped)
		}
	}

	if err == nil {
		v.searchPattern = re
	}
}

// findNext finds the next occurrence of the search pattern
func (v *Viewer) findNext(wrap bool) {
	if v.searchPattern == nil {
		return
	}

	start := v.topLine
	count := v.doc.LineCount()

	if v.searchDown {
		for i := start + 1; i < count; i++ {
			if v.searchPattern.MatchString(v.doc.GetLine(i)) {
				v.topLine = i
				return
			}
		}
		if wrap {
			for i := 0; i < start; i++ {
				if v.searchPattern.MatchString(v.doc.GetLine(i)) {
					v.topLine = i
					return
				}
			}
		}
	} else {
		for i := start - 1; i >= 0; i-- {
			if v.searchPattern.MatchString(v.doc.GetLine(i)) {
				v.topLine = i
				return
			}
		}
		if wrap {
			for i := count - 1; i > start; i-- {
				if v.searchPattern.MatchString(v.doc.GetLine(i)) {
					v.topLine = i
					return
				}
			}
		}
	}
}

// gotoLine navigates to a specific line
func (v *Viewer) gotoLine(input string) {
	input = strings.TrimSpace(input)
	if input == "" {
		return
	}

	// Percentage: "50%"
	if strings.HasSuffix(input, "%") {
		pct, err := strconv.ParseFloat(input[:len(input)-1], 64)
		if err == nil {
			line := int(float64(v.doc.LineCount()) * pct / 100)
			if line < 0 {
				line = 0
			}
			if line >= v.doc.LineCount() {
				line = v.doc.LineCount() - 1
			}
			v.topLine = line
		}
		return
	}

	// Relative: ".5"
	if strings.HasPrefix(input, ".") {
		n, err := strconv.Atoi(input[1:])
		if err == nil {
			v.topLine = v.topLine + n
			v.clampTopLine()
		}
		return
	}

	// Absolute line number
	n, err := strconv.Atoi(input)
	if err == nil {
		v.topLine = n - 1 // 1-based to 0-based
		v.clampTopLine()
	}
}

// scrollDown scrolls down by n screen lines
func (v *Viewer) scrollDown(n int) {
	if v.wrapMode {
		// In wrap mode, we need to count wrapped lines
		screenLines := 0
		lineIdx := v.topLine

		for screenLines < n && lineIdx < v.doc.LineCount() {
			line := v.doc.GetLine(lineIdx)
			expanded := expandTabs(line, v.tabWidth)
			displayWidth := v.screen.Width() - v.lineNumWidth()
			if displayWidth <= 0 {
				displayWidth = 1
			}

			lineScreenLines := (len(expandANSI(expanded)) + displayWidth - 1) / displayWidth
			if lineScreenLines == 0 {
				lineScreenLines = 1
			}

			if screenLines+lineScreenLines > n {
				break
			}
			screenLines += lineScreenLines
			lineIdx++
		}

		if lineIdx > v.topLine {
			v.topLine = lineIdx
		} else {
			v.topLine++
		}
	} else {
		v.topLine += n
	}
	v.clampTopLine()
}

// scrollUp scrolls up by n lines
func (v *Viewer) scrollUp(n int) {
	v.topLine -= n
	if v.topLine < 0 {
		v.topLine = 0
	}
}

// scrollLeft scrolls left by n columns
func (v *Viewer) scrollLeft(n int) {
	v.leftCol -= n
	if v.leftCol < 0 {
		v.leftCol = 0
	}
}

// scrollRight scrolls right by n columns
func (v *Viewer) scrollRight(n int) {
	v.leftCol += n
}

// goToEnd goes to the end of the document
func (v *Viewer) goToEnd() {
	count := v.doc.LineCount()
	if count <= v.contentHeight {
		v.topLine = 0
	} else {
		v.topLine = count - v.contentHeight
	}
}

// clampTopLine clamps topLine to valid range
func (v *Viewer) clampTopLine() {
	count := v.doc.LineCount()
	maxTop := count - 1
	if maxTop < 0 {
		maxTop = 0
	}
	if v.topLine > maxTop {
		v.topLine = maxTop
	}
	if v.topLine < 0 {
		v.topLine = 0
	}
}

// lineNumWidth returns the width used for line numbers
func (v *Viewer) lineNumWidth() int {
	if !v.lineNumMode {
		return 0
	}
	count := v.doc.LineCount()
	if count == 0 {
		return 2
	}
	digits := len(strconv.Itoa(count))
	return digits + 1 // digit + space
}

// hScrollWidth returns the horizontal scroll width in pixels
func (v *Viewer) hScrollWidth() int {
	w := v.opts.HScrollWidth
	if strings.HasSuffix(w, "%") {
		pct, err := strconv.ParseFloat(w[:len(w)-1], 64)
		if err == nil {
			return int(float64(v.screen.Width()) * pct / 100)
		}
	}
	if strings.HasPrefix(w, ".") {
		f, err := strconv.ParseFloat(w, 64)
		if err == nil {
			return int(float64(v.screen.Width()) * f)
		}
	}
	n, err := strconv.Atoi(w)
	if err == nil {
		return n
	}
	return 8 // default
}

// render renders the current view to the screen
func (v *Viewer) render() {
	screen := v.screen
	width := screen.Width()
	height := screen.Height()

	// Update content height based on status line setting
	v.contentHeight = height - 1
	if !v.statusLine {
		v.contentHeight = height
	}

	numWidth := v.lineNumWidth()
	displayWidth := width - numWidth
	if displayWidth <= 0 {
		displayWidth = 1
	}

	lineIdx := v.topLine + v.opts.SkipLines
	screenRow := 1

	// Render header lines first (they stay fixed at top)
	if v.header > 0 {
		for hdr := 0; hdr < v.header && hdr < v.doc.LineCount(); hdr++ {
			line := v.doc.GetLine(hdr)
			v.renderLine(screenRow, hdr, line, numWidth, displayWidth, true, hdr%2 == 1)
			screenRow++
			if screenRow > v.contentHeight {
				break
			}
		}
		// Start content from after header
		if lineIdx < v.header {
			lineIdx = v.header
		}
	}

	// Render content lines
	for screenRow <= v.contentHeight {
		if lineIdx >= v.doc.LineCount() {
			// Show ~ for empty lines
			screen.MoveTo(screenRow, 1)
			screen.ResetStyle()
			fmt.Fprintf(screen.buf, "%-*s", width, "~")
			screenRow++
			lineIdx++
			continue
		}

		line := v.doc.GetLine(lineIdx)

		// Determine if this is an alternate row
		isAlt := v.alternateRows && (lineIdx-v.topLine)%2 == 1

		if v.wrapMode {
			// In wrap mode, render the line and any wrapped portions
			expanded := expandTabs(line, v.tabWidth)
			displayStr := expandANSI(expanded)

			// Apply column offset (leftCol)
			if v.leftCol > 0 && v.leftCol < len(displayStr) {
				displayStr = displayStr[v.leftCol:]
			} else if v.leftCol >= len(displayStr) {
				displayStr = ""
			}

			for screenRow <= v.contentHeight {
				var chunk string
				if len(displayStr) <= displayWidth {
					chunk = displayStr
					displayStr = ""
				} else {
					chunk = displayStr[:displayWidth]
					displayStr = displayStr[displayWidth:]
				}

				screen.MoveTo(screenRow, 1)
				screen.ResetStyle()

				if numWidth > 0 {
					numStr := fmt.Sprintf("%*d", numWidth-1, lineIdx+1)
					fmt.Fprintf(screen.buf, "%s ", numStr)
				}

				if isAlt {
					fmt.Fprintf(screen.buf, CSI+"48;5;235m")
				}
				if v.searchPattern != nil && !v.plain {
					chunk = highlightSearch(chunk, v.searchPattern)
				}
				fmt.Fprintf(screen.buf, "%-*s", displayWidth, chunk)
				if isAlt {
					fmt.Fprintf(screen.buf, AttrReset)
				}

				screenRow++
				if displayStr == "" {
					break
				}
				// For wrapped continuation, don't repeat line number
			}
		} else {
			v.renderLine(screenRow, lineIdx, line, numWidth, displayWidth, false, isAlt)
			screenRow++
		}

		lineIdx++
	}

	// Render status line
	if v.statusLine && height > 0 {
		v.renderStatusLine(height)
	}
}

// renderLine renders a single line at the given row
func (v *Viewer) renderLine(row, lineIdx int, line string, numWidth, displayWidth int, isHeader bool, isAlt bool) {
	screen := v.screen

	screen.MoveTo(row, 1)
	screen.ResetStyle()

	// Line number
	if numWidth > 0 {
		numStr := fmt.Sprintf("%*d", numWidth-1, lineIdx+1)
		if isHeader {
			fmt.Fprintf(screen.buf, CSI+"1m%s "+AttrReset, numStr)
		} else {
			fmt.Fprintf(screen.buf, "%s ", numStr)
		}
	}

	// Apply column offset
	expanded := expandTabs(line, v.tabWidth)
	displayStr := expandANSI(expanded)

	if v.leftCol > 0 {
		// Skip leftCol visual columns
		skip := v.leftCol
		runes := []rune(displayStr)
		for i, r := range runes {
			w := runeWidth(r)
			if skip <= 0 {
				displayStr = string(runes[i:])
				break
			}
			skip -= w
			if i == len(runes)-1 {
				displayStr = ""
			}
		}
	}

	// Truncate to display width
	if len(displayStr) > displayWidth {
		displayStr = truncateToWidth(displayStr, displayWidth)
	}

	// Apply styling
	if isHeader {
		fmt.Fprintf(screen.buf, CSI+"1m")
	} else if isAlt {
		fmt.Fprintf(screen.buf, CSI+"48;5;235m")
	}

	if v.searchPattern != nil && !v.plain {
		displayStr = highlightSearch(displayStr, v.searchPattern)
	}

	// Write the line content with padding
	fmt.Fprintf(screen.buf, "%s", displayStr)

	if isHeader || isAlt {
		fmt.Fprintf(screen.buf, AttrReset)
	}

	// Clear remainder of line
	fmt.Fprintf(screen.buf, ClearToEOL)
}

// renderStatusLine renders the status bar at the bottom
func (v *Viewer) renderStatusLine(row int) {
	screen := v.screen
	width := screen.Width()

	screen.MoveTo(row, 1)

	var status string

	if v.mode != ModeNormal {
		// Show input prompt
		prompt := v.modePrompt()
		status = prompt + v.inputBuf

		// Calculate position info
		posInfo := fmt.Sprintf("(%d/%d)", v.topLine+1, v.doc.LineCount())

		// Pad to width
		padLen := width - len(status) - len(posInfo)
		if padLen < 0 {
			padLen = 0
		}
		status = status + strings.Repeat(" ", padLen) + posInfo
	} else {
		// Normal status: filename + position
		name := v.doc.Name
		if name == "" {
			name = ""
		}

		posInfo := fmt.Sprintf("(%d/%d)", v.topLine+1, v.doc.LineCount())

		left := name + ":"

		// Add message if any
		if v.message != "" {
			left += " " + v.message
		}

		padLen := width - len(left) - len(posInfo)
		if padLen < 1 {
			padLen = 1
		}

		status = left + strings.Repeat(" ", padLen) + posInfo
	}

	// Truncate to screen width
	if len(status) > width {
		status = status[:width]
	}

	fmt.Fprint(screen.buf, status)
	fmt.Fprint(screen.buf, ClearToEOL)
}

// modePrompt returns the prompt string for the current input mode
func (v *Viewer) modePrompt() string {
	prefix := ""
	if v.opts.Incsearch {
		prefix = "(I)"
	}
	switch v.mode {
	case ModeSearch:
		return prefix + "/"
	case ModeBackSearch:
		return prefix + "?"
	case ModeFilter:
		return prefix + "&"
	case ModeGoto:
		return "goto:"
	case ModeHeader:
		return "Header line:"
	case ModeDelimiter:
		return "Delimiter:"
	case ModeSkipLines:
		return "Skip lines:"
	case ModeTabWidth:
		return "Tab width:"
	case ModeMultiColor:
		return "MultiColor:"
	case ModeJumpTarget:
		return "Jump target line:"
	case ModeViewMode:
		return "View mode:"
	case ModeWatchInterval:
		return "Watch interval:"
	case ModeVerticalHeader:
		return "Vertical header:"
	case ModeHeaderColumn:
		return "Header column:"
	case ModeConvertType:
		return "Convert type:"
	}
	return ""
}

// writeScreen writes the current screen content to a writer
func (v *Viewer) writeScreen(w io.Writer) {
	for i := v.topLine; i < v.doc.LineCount() && i < v.topLine+v.contentHeight; i++ {
		line := v.doc.GetLine(i)
		fmt.Fprintln(w, line)
	}
}

// markExitWrite marks the current view for exit write
func (v *Viewer) markExitWrite() {
	for i := v.topLine; i < v.doc.LineCount() && i < v.topLine+v.contentHeight; i++ {
		v.exitLines = append(v.exitLines, v.doc.GetLine(i))
	}
}

// nextMark goes to the next mark
func (v *Viewer) nextMark() {
	for _, m := range v.marks {
		if m > v.topLine {
			v.topLine = m
			return
		}
	}
}

// prevMark goes to the previous mark
func (v *Viewer) prevMark() {
	for i := len(v.marks) - 1; i >= 0; i-- {
		if v.marks[i] < v.topLine {
			v.topLine = v.marks[i]
			return
		}
	}
}

// nextSection goes to the next section (based on section delimiter)
func (v *Viewer) nextSection() {
	if v.opts.SectionDelimiter == "" {
		v.scrollDown(v.contentHeight - 1)
		return
	}

	re, err := regexp.Compile(v.opts.SectionDelimiter)
	if err != nil {
		return
	}

	for i := v.topLine + 1; i < v.doc.LineCount(); i++ {
		if re.MatchString(v.doc.GetLine(i)) {
			v.topLine = i
			return
		}
	}
}

// prevSection goes to the previous section
func (v *Viewer) prevSection() {
	if v.opts.SectionDelimiter == "" {
		v.scrollUp(v.contentHeight - 1)
		return
	}

	re, err := regexp.Compile(v.opts.SectionDelimiter)
	if err != nil {
		return
	}

	for i := v.topLine - 1; i >= 0; i-- {
		if re.MatchString(v.doc.GetLine(i)) {
			v.topLine = i
			return
		}
	}
}

// lastSection goes to the last section
func (v *Viewer) lastSection() {
	if v.opts.SectionDelimiter == "" {
		v.goToEnd()
		return
	}

	re, err := regexp.Compile(v.opts.SectionDelimiter)
	if err != nil {
		return
	}

	for i := v.doc.LineCount() - 1; i >= 0; i-- {
		if re.MatchString(v.doc.GetLine(i)) {
			v.topLine = i
			return
		}
	}
}

// showHelp shows the help document
func (v *Viewer) showHelp() {
	// Create a temporary document with help content
	helpDoc := &Document{
		Name: "Help",
	}
	helpLines := strings.Split(helpKeyContent(), "\n")
	helpDoc.lines = helpLines

	// Create a new viewer for the help
	helpViewer := NewViewer(helpDoc, v.screen, v.opts)
	helpViewer.Run()
}

// highlightSearch highlights search matches in a string
func highlightSearch(s string, re *regexp.Regexp) string {
	if re == nil {
		return s
	}
	return re.ReplaceAllStringFunc(s, func(m string) string {
		return CSI + "7m" + m + AttrReset
	})
}

// expandTabs expands tab characters
func expandTabs(s string, tabWidth int) string {
	if tabWidth <= 0 {
		tabWidth = 8
	}
	if !strings.Contains(s, "\t") {
		return s
	}

	var sb strings.Builder
	col := 0
	for _, r := range s {
		if r == '\t' {
			spaces := tabWidth - (col % tabWidth)
			for i := 0; i < spaces; i++ {
				sb.WriteByte(' ')
			}
			col += spaces
		} else {
			sb.WriteRune(r)
			col += runeWidth(r)
		}
	}
	return sb.String()
}

// expandANSI strips ANSI escape sequences for width calculation
// but preserves them in the string
func expandANSI(s string) string {
	return s
}

// WriteToStdout writes the document content to stdout for non-interactive mode
func WriteToStdout(doc *Document) {
	for i := 0; i < doc.LineCount(); i++ {
		fmt.Println(doc.GetLine(i))
	}
}

