package oviewer

import (
	"fmt"
	"io"
	"os"
	"sort"
)

// Run is the main entry point for ov
func Run(version, revision string) error {
	args := os.Args[1:]

	// Check for cobra internal commands first
	if len(args) > 0 && (args[0] == "__complete" || args[0] == "__completeNoDesc") {
		return handleCompletion(args)
	}

	opts, err := ParseArgs(args)
	if err != nil {
		return fmt.Errorf("unknown flag: %s", extractFlagName(err.Error()))
	}

	// Handle simple output flags first
	if opts.Help {
		PrintHelp()
		return nil
	}

	if opts.Version {
		fmt.Printf("ov version %s rev:%s\n", version, revision)
		return nil
	}

	if opts.HelpKey {
		PrintHelpKey()
		return nil
	}

	if opts.Completion != "" {
		PrintCompletion(opts.Completion)
		return nil
	}

	// Load config file
	cfg := DefaultConfig()
	configPath := opts.ConfigFile
	if configPath == "" {
		configPath = GetConfigPath()
	}
	if configPath != "" {
		if loaded, err := LoadConfig(configPath); err == nil {
			cfg = loaded
		}
		// Silently ignore config load errors
	}

	// Apply config defaults if flags weren't set
	applyConfigDefaults(opts, cfg)

	if opts.ListViewModes {
		// Print view modes from config
		modes := []string{"general"}
		for name := range cfg.Mode {
			modes = append(modes, name)
		}
		sort.Strings(modes[1:]) // Sort all but "general"
		for _, m := range modes {
			fmt.Println(m)
		}
		return nil
	}

	// Determine if we're in interactive mode
	isInteractive := isTerminal(int(os.Stdout.Fd()))

	if !isInteractive && !opts.ForceScreen {
		// Non-interactive mode: just output the content
		return runNonInteractive(opts)
	}

	// Interactive mode
	return runInteractive(opts)
}

// applyConfigDefaults applies config defaults that weren't overridden by flags
func applyConfigDefaults(opts *Options, cfg *Config) {
	// Apply general config defaults
	// (flags override config, but if not specified, use config)
	if cfg.General.TabWidth > 0 && opts.TabWidth == 8 {
		opts.TabWidth = cfg.General.TabWidth
	}
	if !opts.WrapMode && cfg.General.WrapMode {
		// opts.WrapMode was set by user (false), don't override
	}
	// Apply view mode if specified
	if opts.ViewMode != "" {
		if mc, ok := cfg.Mode[opts.ViewMode]; ok {
			applyModeToOptions(opts, mc)
		}
	}
