// applyModeToOptions applies a mode config to options
func applyModeToOptions(opts *Options, mc ModeConfig) {
	if mc.Header > 0 {
		opts.Header = mc.Header
	}
	if mc.TabWidth > 0 {
		opts.TabWidth = mc.TabWidth
	}
	if mc.ColumnDelimiter != "" {
		opts.ColumnDelimiter = mc.ColumnDelimiter
	}
	if mc.SectionDelimiter != "" {
		opts.SectionDelimiter = mc.SectionDelimiter
	}
	// Boolean flags - only apply if explicitly set
	if mc.AlternateRows {
		opts.AlternateRows = true
	}
	if mc.ColumnMode {
		opts.ColumnMode = true
	}
	if mc.LineNumMode {
		opts.LineNumMode = true
	}
}

