	if err != nil {
		return err
	}

	// Handle simple output flags first
	if opts.Help {
		PrintHelp()
		return nil
	}

	if opts.Version {
		fmt.Printf("ov version %s rev:%s\n", version, revision)
		return nil
	}

	if opts.HelpKey {
		PrintHelpKey()
		return nil
	}

	if opts.Completion != "" {
		PrintCompletion(opts.Completion)
		return nil
	}

	// Load config file
	cfg := DefaultConfig()
	configPath := opts.ConfigFile
	if configPath == "" {
		configPath = GetConfigPath()
	}
	if configPath != "" {
		if loaded, err := LoadConfig(configPath); err == nil {
			cfg = loaded
		}
		// Silently ignore config load errors
	}

	// Apply config defaults if flags weren't set
	applyConfigDefaults(opts, cfg)

	if opts.ListViewModes {
		// Print view modes from config
		modes := []string{"general"}
		for name := range cfg.Mode {
			modes = append(modes, name)
		}
		sort.Strings(modes[1:]) // Sort all but "general"
		for _, m := range modes {
			fmt.Println(m)
		}
		return nil
	}

	// Determine if we're in interactive mode
	interactive := isTerminalFd(int(os.Stdout.Fd()))

	if !interactive && !opts.ForceScreen {
		// Non-interactive mode: just output the content
		return runNonInteractive(opts)
	}

	// Interactive mode
	return runInteractive(opts)
}

// applyConfigDefaults applies config defaults that weren't overridden by flags
func applyConfigDefaults(opts *Options, cfg *Config) {
	// Apply view mode if specified
	if opts.ViewMode != "" {
		if mc, ok := cfg.Mode[opts.ViewMode]; ok {
			applyModeToOptions(opts, mc)
		}
	}
}

// applyModeToOptions applies a mode config to options
func applyModeToOptions(opts *Options, mc ModeConfig) {
	if mc.Header > 0 {
		opts.Header = mc.Header
	}
	if mc.TabWidth > 0 {
		opts.TabWidth = mc.TabWidth
	}
	if mc.ColumnDelimiter != "" {
		opts.ColumnDelimiter = mc.ColumnDelimiter
	}
	if mc.SectionDelimiter != "" {
		opts.SectionDelimiter = mc.SectionDelimiter
	}
	if mc.AlternateRows {
		opts.AlternateRows = true
	}
	if mc.ColumnMode {
		opts.ColumnMode = true
	}
	if mc.LineNumMode {
		opts.LineNumMode = true
	}
}

// runNonInteractive runs in non-interactive mode (stdout is not a TTY)
func runNonInteractive(opts *Options) error {
	// Determine input source
	if len(opts.Files) == 0 {
		// Read from stdin
		_, err := io.Copy(os.Stdout, os.Stdin)
		return err
	}

	// Output first file (ov shows one file at a time in interactive mode,
	// in non-interactive mode it outputs the first file)
	filename := opts.Files[0]

	f, err := os.Open(filename)
	if err != nil {
		return err
	}
	defer f.Close()

	_, err = io.Copy(os.Stdout, f)
	return err
}

// runInteractive runs in interactive TUI mode
func runInteractive(opts *Options) error {
	// Create screen
	screen, err := NewScreen(opts.DisableMouse)
	if err != nil {
		return err
	}

	// Load documents
	var doc *Document

	if len(opts.Files) == 0 {
		// Read from stdin
		// Check if stdin is a TTY (no piped input)
		if isTerminalFd(int(os.Stdin.Fd())) {
			return fmt.Errorf("missing file")
		}
		doc, err = NewDocument("", opts.SkipExtract)
		if err != nil {
			return err
		}
	} else {
		doc, err = NewDocument(opts.Files[0], opts.SkipExtract)
		if err != nil {
			return err
		}
	}

	// Initialize screen
	if err := screen.Init(); err != nil {
		return err
	}
	defer screen.Close()

	// Create and run viewer
	viewer := NewViewer(doc, screen, opts)

	if err := viewer.Run(); err != nil {
		return err
	}

	// Handle exit write
	if opts.ExitWrite {
		viewer.writeScreen(os.Stdout)
	}

	return nil
}

// handleCompletion handles cobra's __complete and __completeNoDesc commands
func handleCompletion(args []string) error {
	// args[0] is "__complete" or "__completeNoDesc"
	// The remaining args are the partial command line

	remaining := args[1:]

	// Check if we're completing a flag value
	if len(remaining) >= 2 {
		prevFlag := remaining[len(remaining)-2]
		switch prevFlag {
		case "--config", "--completion", "--caption", "--column-delimiter",
			"-d", "--converter", "--filter", "--non-match-filter",
			"--pattern", "--section-delimiter", "--view-mode", "-m",
			"--watch", "-T":
			// String completions - no file completion
			fmt.Print(":4\nCompletion ended with directive: ShellCompDirectiveNoFileComp\n")
			return nil
		}
	}

	// Check the last argument
	if len(remaining) > 0 {
		last := remaining[len(remaining)-1]
		// If it starts with --, suggest flags
		if last == "--config" || last == "--header" || last == "--tab-width" {
			fmt.Print(":4\nCompletion ended with directive: ShellCompDirectiveNoFileComp\n")
			return nil
		}
	}

	// Default: file completion
	fmt.Print(":0\nCompletion ended with directive: ShellCompDirectiveDefault\n")
	return nil
}
